INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A ring frame runs at an average of 18,000 rpm, spins 20 TPI yarn, and runs at 85% efficiency for an 8-hour shift. Approximately how many inches of yarn does ONE spindle produce in that shift (ignoring stoppage details beyond the efficiency factor)?', '["≈ 367,200 inches","≈ 900 inches","≈ 432,000 inches","≈ 18,000 inches"]'::jsonb, '≈ 367,200 inches', 'Delivery speed = rpm ÷ TPI = 18,000 ÷ 20 = 900 inches/min. Over 8 hours = 480 minutes at 100% efficiency: 900 × 480 = 432,000 inches. Applying 85% efficiency: 432,000 × 0.85 ≈ 367,200 inches per spindle.', 2, '{"production-calculation"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'A mill''s raw cotton input for a production run is 1,000 kg, and total processing waste (blow room + card + other losses) is 12%. Approximately how much usable fiber output results?', '["880 kg","1,120 kg","120 kg","988 kg"]'::jsonb, '880 kg', 'Usable output = input × (1 − waste%) = 1,000 × (1 − 0.12) = 1,000 × 0.88 = 880 kg.', 1, '{"waste-percentage-calc"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'A mill''s raw cotton input for a production run is 2,500 kg, and total processing waste is 8%. Approximately how much usable fiber output results?', '["2,300 kg","2,700 kg","200 kg","2,308 kg"]'::jsonb, '2,300 kg', 'Usable output = input × (1 − waste%) = 2,500 × (1 − 0.08) = 2,500 × 0.92 = 2,300 kg.', 1, '{"waste-percentage-calc"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'A comber removes 18% of the input fiber as noil. For 400 kg of lap fed into the comber, how much combed fiber (net of noil) results?', '["328 kg","72 kg","382 kg","400 kg"]'::jsonb, '328 kg', 'Combed output = input × (1 − noil%) = 400 × (1 − 0.18) = 400 × 0.82 = 328 kg.', 1, '{"noil-calculation"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'A comber removes 15% of the input fiber as noil. For 600 kg of lap fed into the comber, how much combed fiber (net of noil) results?', '["510 kg","90 kg","585 kg","600 kg"]'::jsonb, '510 kg', 'Combed output = input × (1 − noil%) = 600 × (1 − 0.15) = 600 × 0.85 = 510 kg.', 1, '{"noil-calculation"}'::text[]);
